import{_ as s,o,c as n,a2 as a}from"./chunks/framework.C3idr2hZ.js";const r="/orc/screens/dashboard-light.png",i="/orc/screens/session-home-desktop.png",d="/orc/screens/session-home-phone.png",c="/orc/screens/session-list-phone.png",h="/orc/screens/session-inspector-phone.png",l="/orc/screens/session-inspector-changes-phone.png",p="/orc/screens/session-inspector-pr-phone.png",g="/orc/screens/session-inspector-files-phone.png",t="/orc/screens/session-recents-desktop.png",u="/orc/screens/session-recents-phone.png",m="/orc/screens/session-projects-desktop.png",w="/orc/screens/session-projects-phone.png",f="/orc/screens/chat-fork-desktop.png",b="/orc/screens/chat-fork-phone.png",k="/orc/screens/dashboard.png",v="/orc/screens/tasks.png",y="/orc/screens/task-detail.png",C="/orc/screens/task-flow.png",S="/orc/screens/desktop-side-chat-plain.png",T="/orc/screens/phone-chat-preview-closed.png",x="/orc/screens/desktop-chat-browser-control.png",P="/orc/screens/desktop-browser-settings.png",_="/orc/screens/desktop-preview-changes-wide.png",A="/orc/screens/desktop-preview-changes-phone.png",q="/orc/screens/desktop-preview-markdown.png",R="/orc/screens/terminals.png",O="/orc/screens/knowledge.png",j="/orc/screens/jobs.png",I="/orc/screens/jobs-editor.png",E="/orc/screens/settings.png",L="/orc/screens/chat-hosts-picker.png",B="/orc/screens/desktop-connection.png",D="/orc/screens/desktop-connection-phone.png",H="/orc/screens/settings-agents.png",F="/orc/screens/chat-agent-picker.png",M="/orc/screens/chat-run-in-1440.png",W="/orc/screens/chat-run-in-390.png",U="/orc/screens/chat-session-composer-desktop.png",G="/orc/screens/chat-session-composer-phone.png",N="/orc/screens/chat-session-settings-overview-desktop.png",K="/orc/screens/chat-session-settings-analytics-desktop.png",z="/orc/screens/chat-session-settings-customize-phone.png",J="/orc/screens/chat-composer-390.png",se=JSON.parse('{"title":"Desktop app and web dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"docs/desktop-and-web.md","filePath":"docs/desktop-and-web.md","lastUpdated":1794707668000}'),V={name:"docs/desktop-and-web.md"};function Q($,e,X,Z,Y,ee){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="desktop-app-and-web-dashboard" tabindex="-1">Desktop app and web dashboard <a class="header-anchor" href="#desktop-app-and-web-dashboard" aria-label="Permalink to &quot;Desktop app and web dashboard&quot;">​</a></h1><p>A tour of every page in the ORC dashboard and what the desktop app adds on top of it.</p><p>The dashboard is served by the daemon at <code>http://localhost:7700</code>. The desktop app shows the same dashboard in its own window, so everything below applies to both.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Contents</th></tr></thead><tbody><tr><td>Sidebar</td><td>Activity, Chat, Tasks, Knowledge, Terminals, Library, Settings. Shows the execution host, for example <code>Connected (local)</code>.</td></tr><tr><td>Project picker</td><td>Scopes most pages to one project, all projects, or unassigned items. A project with sessions waiting on you shows how many.</td></tr><tr><td>Chat panel</td><td>Talk to any enabled coding agent from any page. Pick the agent and model at the top. Claude and Codex run natively; OpenCode uses direct ACP; other agents run through ACPX.</td></tr><tr><td>Command palette</td><td><strong>Ctrl+K</strong> (<strong>Cmd+K</strong> on macOS) to search and run commands</td></tr><tr><td>Next session</td><td><strong>Alt+J</strong> (<strong>Option+J</strong> on macOS) opens the next session that needs you, then the next finished session you have not seen. It does nothing while you are typing.</td></tr></tbody></table><p>Popup menus and pickers across the dashboard close when you tap outside or press Escape, including project, session, document and terminal actions. Tapping the terminal canvas also dismisses an open menu. Interacting inside a picker or its folder dialog keeps it usable without discarding your draft.</p><p>Pages are grouped in the sidebar:</p><table tabindex="0"><thead><tr><th>Group</th><th>Pages</th></tr></thead><tbody><tr><td>Activity</td><td>Activity, Jobs, Webhooks, Audit</td></tr><tr><td>Chat</td><td>Chat</td></tr><tr><td>Tasks</td><td>Tasks</td></tr><tr><td>Knowledge</td><td>Knowledge base, Memories</td></tr><tr><td>Terminals</td><td>Terminals</td></tr><tr><td>Library</td><td>Skills, Packages, Agents, Rules, Scratchpads</td></tr><tr><td>Settings</td><td>Settings</td></tr></tbody></table><p>Projects has its own page at <code>/projects</code>. Every page has a shareable URL.</p><p>Switch between the dark and light themes in <strong>Settings → General → Appearance</strong>, or with the theme command in the command palette:</p><p><img src="'+r+'" alt="Dashboard in the light theme"></p><h2 id="chat-page" tabindex="-1">Chat page <a class="header-anchor" href="#chat-page" aria-label="Permalink to &quot;Chat page&quot;">​</a></h2><p><strong>Chat</strong> in the sidebar opens the chat page at <code>/chat</code>. It is a regular page: the workspace header keeps your navigation and notifications, and <strong>Chat</strong> shows as the active page. The sidebar collapses to its icon rail while a conversation is open, including the side chat, to give the conversation the width; leaving chat restores the width you had, and expanding it during chat keeps your choice. The chat panel&#39;s full-screen button in the <strong>Terminals</strong> session list opens the same page.</p><p>Below 1280px wide, the chat has no side panel: starting a chat from any page opens the chat page instead.</p><ul><li><strong>Session list</strong>: chats, coding agents running in ORC terminals, and live sessions discovered from every coding agent, each with its state. The full-screen session home also lists running shell terminals. Click a chat to read it, a terminal agent to see its terminal, or a discovered session to resume it in chat. Every list has the same search, state filters, agent filter, sort order, hidden-session toggle and stable ordering. <ul><li><strong>Search</strong> matches titles and summaries; the sparkle toggle also searches inside transcripts (ripgrep) and archived conversations (embeddings when configured). The result snippet shows the matching passage.</li><li><strong>Agent</strong> filters by coding agent, merging Cursor IDE and Cursor CLI into one choice. <strong>Sort</strong> offers newest/oldest last activity or agent groups (newest first inside each agent); the choice is remembered.</li><li>Providers whose native store chat cannot resume (Cursor) open the read-only session view instead of resuming.</li><li>A session can be hidden from the list and shown again with the <strong>hidden</strong> toggle; both survive reloads.</li><li>Collapse the list to a rail of icons with its state marks; expand it again from the rail.</li><li><strong>Projects</strong>, the default view, groups sessions under their project (unassigned sessions get their own group); the project of the session you are viewing opens and marks that session, expand any other project to see its sessions, and use a project&#39;s <strong>+</strong> button to start a chat in the project&#39;s folder. <strong>Recents</strong> lists every session by last activity, newest first. A session&#39;s working folder decides its project: the most specific project folder wins, a worktree resolves to its shared checkout, and a session without a recorded project is matched to a project whose folder contains its working folder. Both views follow the project selected in the workspace header; pick <strong>All projects</strong> to browse every project, and sessions in archived or paused projects stay listed under their project. Opening a session from the list adopts its project when the header is on <strong>All projects</strong> or <strong>Unassigned</strong>, so the list and notification inbox follow the work you opened.</li><li>Opening a session keeps its place in the list; sending a message is what moves it to the top. State filters still move rows as their status changes. While you hover or keyboard-focus the list, its order freezes and a pill offers to apply the new order. The header&#39;s refresh button re-imports agent sessions, then refreshes threads, live sessions and archive.</li></ul></li><li><strong>Inspector</strong>: the panel button in the header opens one panel with <strong>Overview</strong>, <strong>Changes</strong> and <strong>Files</strong> on desktop and phone. Overview shows the host, folder, branch, changed files, linked task and the branch&#39;s pull request with its state, CI state and GitHub link; a checkout on a detached HEAD says so instead of reporting missing GitHub authentication. When a terminal is running in that folder, <strong>Changes</strong> combines the working-tree review (staging and commit) with the branch&#39;s PR review (diff, comments and an <strong>Open on GitHub</strong> link) behind Local / PR modes, and <strong>Files</strong> browses and edits the checkout. In the Electron desktop app the same panel adds a desktop-only <strong>Browser</strong> tab. On a phone the inspector is a full page.</li><li><strong>Terminal drawer</strong>: the terminal button in the header opens a shell in the session&#39;s folder below the conversation. Its header names the terminal, its live state and the folder/host. <strong>Expand</strong> gives the terminal the conversation&#39;s space and <strong>Close</strong> hides it, leaving the shell running. On a touch screen, swipe inside the terminal to scroll; a tap still opens the keyboard, and a swipe does not.</li><li><strong>Continue in terminal</strong>: when the response has finished and the session is idle, <strong>Continue in terminal</strong> in the session actions menu resumes that origin session in its native agent. This works for every native chat agent (Claude Code, Codex, Gemini CLI, OpenCode and Pi), including sessions you have hidden from the session list. The terminal opens as the chat view&#39;s main pane, leaving the conversation mounted behind it; the back arrow returns to the chat without losing the terminal or your draft. An already running terminal for that session is reused instead of started twice; if it has exited, a new one resumes the session. A link to an exited or deleted terminal says it is no longer running and the back arrow still returns to the chat.</li><li>Drag a splitter, or focus it and use the arrow keys, to resize the list, inspector or drawer. Double-click to reset. The width is remembered.</li><li><strong>Message actions</strong>: hover a response (they stay visible on touch screens) to copy it, fork the chat at that response, and see how long it took. A fork reuses the agent&#39;s native session when the response is the latest one and the agent supports it; otherwise the new chat carries a bounded, tool-aware replay up to that response. A notice at the top of the forked chat names the source, the mode it used, what context it carried, and links back to the source chat.</li><li>The page keeps the workspace header and its single notification bell. On desktop <strong>Close chat</strong> returns to the page you came from; on a phone the chat is a regular page, so you leave it with Back or the navigation drawer.</li><li>The URL keeps the selected session and which panels are open, so reload and Back restore them.</li><li>The header shows the recorded project and session title. Unlinked terminal agents show <strong>Unknown</strong> until agent activity supplies a state; they appear only in All projects while project ownership is unavailable. The Activity session list uses the same compact row design, retaining search, filters, task links and resume actions.</li></ul><p>On a phone (below 768px) the chat is a touch-first surface. The header keeps the session title, <strong>Sessions</strong>, <strong>New</strong> and the actions menu on one line, with the <strong>Terminal</strong>, <strong>Inspector</strong>, <strong>Refresh</strong> and <strong>Compact</strong> controls on a second line (right-aligned; it collapses when the viewport gets very short, such as with the software keyboard on a small screen, and the same actions stay available in the <strong>⋯</strong> menu). <strong>Sessions</strong>, the <strong>Inspector</strong> and the <strong>Terminal</strong> open as full pages over the conversation, which stays mounted underneath so streams and drafts survive. They follow your finger:</p><ul><li>Swipe left from the right edge to open <strong>Sessions</strong>; swipe right to close it.</li><li>Swipe right from the left edge to open the <strong>Inspector</strong>; swipe left to close it.</li><li>Pull down on the chat header (or tap <strong>Terminal</strong>) to open the terminal page; it shows the same name, state and folder header, and swipe up on that header, tap the close button or press Escape to close it.</li><li>Pull down from the very top of the screen with two fingers to open <strong>Notifications</strong>, like the system shade; Back returns to the chat.</li></ul><p>Swipes that start inside code blocks, diffs or the terminal canvas stay with that content. Every page also opens from its header button, closes with its back button or Escape, and is kept in the URL: <code>sessionList=show</code>, <code>inspector=overview|diff|files|browser</code> and <code>drawer=terminal</code> (older <code>inspector=pr</code> links open the Changes tab&#39;s PR mode; <code>browser</code> opens the desktop-only Browser tab and falls back to Overview on the web). Reload, Back and Forward restore the page, and the URL is shareable. The three-dot <strong>Session actions</strong> menu shows labeled actions with touch-sized rows on phones. It closes when you tap elsewhere in the chat or press Escape. Choosing an action also closes the menu; opening Session settings keeps the conversation and your draft in place. Agent, workspace and branch pickers also close when you tap outside them. Back and Forward move between the chat and the page you opened it from, just like any other page.</p><p><img src="'+i+'" alt="Session home with its inspector and demo data"></p><img src="'+d+'" alt="Phone conversation with the Terminal and Inspector header buttons" width="260"><img src="'+c+'" alt="Full-screen session list on a phone" width="260"><p>The phone inspector: branch and pull-request summary, the combined Changes tab (working-tree and PR review) and the file editor.</p><img src="'+h+'" alt="Phone inspector overview with branch and pull request cards" width="260"><img src="'+l+'" alt="Phone inspector Changes tab with the working-tree diff" width="260"><img src="'+p+'" alt="Phone inspector Changes tab in PR mode with the PR diff" width="260"><img src="'+g+'" alt="Phone inspector Files tab with the file editor" width="260"><p>The session list&#39;s <strong>Recents</strong> and <strong>Projects</strong> views, ordered by last activity:</p><p><img src="'+t+'" alt="Session list Recents view, newest first"></p><img src="'+u+'" alt="Session list Recents view on a phone" width="260"><img src="'+m+'" alt="Session list grouped by project on desktop" width="640"><img src="'+w+'" alt="Session list grouped by project on a phone" width="260"><p>Forking at a response copies the conversation into a new chat. The notice names the source, whether the fork continued the agent&#39;s native session or carried a context replay, and what that replay included.</p><img src="'+f+'" alt="Fork notice above the copied messages in a forked chat" width="320"><img src="'+b+'" alt="The same fork notice on a phone" width="260"><h2 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h2><p><img src="'+k+'" alt="Activity"></p><p>The <strong>Activity</strong> page: task metrics plus recent jobs, memories and sessions for the selected project.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p><img src="'+v+'" alt="Tasks"></p><p>The task board. Switch between <strong>Board</strong> (kanban) and <strong>Table</strong> views and filter the list. The GitHub panel lists issues and pull requests from known repositories (yours, assigned to you, or all open) and links them to tasks.</p><p>Open a task to see its body, status, comments, linked sessions and Git links, and its flow run:</p><p><img src="'+y+'" alt="Task detail"></p><p><strong>Edit task → View flow</strong> shows the nodes and edges of the task&#39;s <a href="./task-flows">flow</a>, including loops back for review:</p><p><img src="'+C+'" alt="Task flow"></p><h2 id="session-history-and-viewer" tabindex="-1">Session history and viewer <a class="header-anchor" href="#session-history-and-viewer" aria-label="Permalink to &quot;Session history and viewer&quot;">​</a></h2><p><img src="'+t+'" alt="Session list and conversation"></p><p>Live and ended sessions from Claude Code, Codex, Cursor, Gemini CLI, OpenCode and Pi appear in the chat page&#39;s session list on this machine or the selected host. Working sessions update live; a session that finished after you last opened it shows <strong>Done</strong> until you open it, and this browser remembers what you have seen. Ended sessions stay listed by default. See <a href="./live-sessions">Live sessions</a>.</p><p>Filter with <strong>All</strong>, <strong>Needs you</strong>, <strong>Working</strong> and <strong>Done</strong>; each filter shows its count, and failed sessions count as Needs you. While your pointer is over the list, or a row has keyboard focus, rows stay where they are and an <strong>N updated</strong> pill applies the new order when you choose it.</p><p>The <strong>view</strong> button on a session row opens the read-only viewer: transcript search with match navigation, tokens and start/end timing, task link, rename, hide, scratchpads, cache usage, lineage and the queued-message inbox. Resumable sessions also offer <strong>Continue in chat</strong> and a copyable CLI resume command. Cursor sessions stay readable here because chat cannot resume Cursor&#39;s separate CLI store. Archived sessions open the same viewer for their stored transcript and offer resume into chat from a pushed commit.</p><h2 id="terminals" tabindex="-1">Terminals <a class="header-anchor" href="#terminals" aria-label="Permalink to &quot;Terminals&quot;">​</a></h2><h3 id="desktop-browser-inspector-and-editor" tabindex="-1">Desktop browser, inspector and editor <a class="header-anchor" href="#desktop-browser-inspector-and-editor" aria-label="Permalink to &quot;Desktop browser, inspector and editor&quot;">​</a></h3><p>In the Electron desktop app, <strong>File → Browser and files</strong> (Ctrl/Cmd+Shift+B), or <strong>Browser and files</strong> in the tray menu, opens the inspector&#39;s <strong>Browser</strong> tab beside your conversation. There is no second panel: the header&#39;s panel button opens the same inspector on desktop and web, and the Browser tab appears only in the desktop app. Chat links and file attachments open in that tab. Enter an HTTP/HTTPS address and use Back, Forward and Reload. The external-link icon opens the page in your system browser; Ctrl/Cmd-clicking a web link does the same. The panel belongs to the chat page; the side chat stays a plain conversation with no browser, file or agent-control entry points.</p><p><img src="'+S+'" alt="The side chat without the inspector"></p><img src="'+T+'" alt="The chat page on a phone before the inspector opens" width="260"><p>Each conversation keeps its own browser and file tabs within the Browser tab. The inspector stays docked beside the conversation and opens when you ask for it, follow a link or an agent preview arrives; drag the divider (or use arrow keys on it) to resize. The <strong>Files</strong> tab browses the checkout of a running terminal in the session&#39;s folder and opens a file in an editor tab. Closing the panel keeps tabs and drafts in memory; closing a modified file asks before discarding it. Reloading or quitting discards these previews after the unsaved-change warning.</p><p>The <strong>Changes</strong> tab shows the working-tree changes of the terminal running in the session&#39;s folder, reusing the terminal workspace&#39;s Git panel: the changed-file list, unified or side-by-side diffs, staging and commit, and a GitHub link for the branch&#39;s PR. <strong>Open file</strong> opens a changed file in the inspector&#39;s Files tab; the copy icon copies the changed file&#39;s path to the clipboard. The commit draft, filters and selection are kept per terminal, so closing the panel or switching chats does not lose them. Wide panels split the file list and the diff; narrow panels and phones combine them behind the files toggle. When no terminal is running in the folder, the <strong>Overview</strong> says so quietly and offers <strong>Open terminal</strong>; a failed terminal list shows an error with <strong>Retry</strong>. Pull-request review lives in the terminal workspace and in the inspector&#39;s combined <strong>Changes</strong> tab (its PR mode).</p><p>The folder icon (<strong>Open file</strong>) uses the native picker for local files. Chat and MCP file paths resolve inside the selected session&#39;s folder on its execution host; paths outside that folder and symlinks escaping it are denied. Remote file previews require Python 3 on the SSH host. Files must be UTF-8 text up to 1 MiB. Markdown has Read, Edit and Split modes; code uses the existing editor. Text up to 200 KB can be saved explicitly. A save fails if the file changed on disk, keeping your draft until you reload or resolve the change. HTML stays source code. The external-link icon opens the source in VS Code, including known SSH hosts; it is disabled when the desktop cannot identify a remote API host&#39;s filesystem.</p><p>PNG, JPEG, GIF, WebP, BMP and ICO images can also be previewed, up to 8 MiB and 16 megapixels for native-picker images. Images are read-only; native-picker images use native decoding and display a static image. Workspace images use the browser&#39;s image decoder. PDF and Office previews are not included.</p><p>The browser uses a separate session without ORC&#39;s API credentials, cookies or desktop bridge. Camera, microphone, location and other site permissions are blocked. Browser downloads are staged privately (16 MB each, four across the app); <strong>Browser profile, display &amp; recording</strong> lists their status and saves completed files to the selected chat workspace. Interrupted/failed downloads are never reported as saved. Each chat starts with a temporary cookie/storage profile. <strong>Settings → General → Browser → Saved browser profiles</strong> creates named profiles; select one under <strong>Browser profile, display &amp; recording</strong> in the Browser tab to remember site logins. Selecting the same profile in another chat explicitly shares that profile&#39;s site storage. Temporary chats stay isolated. Profile choices and saved cookies survive app restart; session-only cookies follow the site&#39;s expiry rules. Switching profiles closes that chat&#39;s browser tabs after confirmation and preserves file drafts. Use <strong>+</strong> to open a browser tab and each tab&#39;s close button to close it. Popups open another isolated tab. Limits are eight tabs per chat and 24 total; reaching a limit asks you to close a tab, without eviction. Tab IDs, URLs and the selected tab restore when you return after app restart. Temporary mode does not persist cookies; saved tab URLs are still restored. Browser settings also offers profile rename and removal. Removal asks for native confirmation, closes its tabs, clears cookies/site data/cache and resets chat selections.</p><p><strong>Import selected browser logins</strong>, under Browser settings, connects to a local Chrome/Edge debugging endpoint you explicitly enable. Choose the destination ORC profile, enter the loopback debugging port, approve any source-browser prompt, then select sites from its open pages. Only those sites&#39; applicable cookies are copied; their values and the source connection never reach agents or the API. The connection closes after import or cancellation. Live transfer copies cookies applicable to the selected site&#39;s root and currently open page path; passwords, localStorage, IndexedDB and device-bound sessions are not transferred. Partitioned cookies are skipped and counts are reported. Verify the login; some sites require signing in again. Modern Windows Chrome/Edge app-bound cookie files cannot be decrypted by ORC. Chrome&#39;s newer native consent flow and Mac/Linux interaction have not been validated here; the verified source was an isolated Windows Edge profile with a loopback debugging port. Existing personal profiles may not expose one.</p><p><strong>Scan browser profiles</strong> provides direct cookie-store import from Firefox/Zen, Safari on macOS, and supported Chromium-family stores on macOS/Linux. Legacy Windows Helium DPAPI stores are supported; app-bound Windows stores require the live connection. Select a source profile and individual sites. Reads use readonly SQLite snapshots; keys are obtained only after selection through OS facilities. macOS may request Keychain/Full Disk Access approval; Linux encrypted stores need <code>secret-tool</code> and an unlocked Secret Service. Missing keys and skipped cookies are reported, never treated as a guaranteed login. Containers and partitioned cookies are excluded. Direct Firefox import was exercised with isolated Windows demo data; other OS integrations still require their native platform acceptance checks.</p><p>Expand <strong>Browser display &amp; recording</strong> to change appearance/viewport, record the guest page, save WebM to the chat workspace, and play/download it. UI recording lasts up to 60 seconds; agent requests can choose up to 180 seconds. Recordings are limited to 16 MB and contain only the browser guest, without audio or ORC UI. If workspace saving fails, the completed file remains downloadable in that window.</p><p>Agents can use <a href="./mcp#desktop-preview-tools">preview MCP tools</a> to show a file or URL in the selected conversation. <strong>Allow agent browser control</strong>, on by default, is controlled in the chat&#39;s <strong>Session settings</strong> before you open a preview. It permits snapshots, screenshots, clicking, typing, key presses, scrolling, hovering, selecting, dragging, condition waits, guest JavaScript evaluation, cross-origin frame targeting, semantic locators, dialogs, recording, appearance, viewport changes and explicit workspace-file uploads/download retrieval. This includes pages you sign into there. Turning the switch off revokes control. These tools cannot inspect the ORC app or its bridge or edit preview files. Upload paths must remain inside the chat&#39;s trusted workspace. The guest has a minimal standard <code>prompt()</code> adapter because Electron disables that browser function; it exposes no application API, credentials, filesystem access or general IPC. Browser content is untrusted page data, never agent instructions. If a mutating browser command is still pending when control is revoked or its guest is hidden/switched, ORC closes that guest to prevent delayed execution. The tab shows an interruption message; <strong>Reload</strong> restores its URL and profile. File drafts are preserved. An evaluation timeout can require the same recovery.</p><p><img src="'+x+'" alt="Browser access in a demo chat&#39;s Session settings"></p><p><strong>Settings → General → Browser</strong> controls agent browser access for the whole desktop and whether chat web links open in ORC or your system browser. Settings are stored in <code>browser-preferences.json</code> in Electron&#39;s user-data folder and survive restarts. Per-chat permissions use <code>browser-chat-permissions.json</code>; named profile metadata and explicit chat selections use <code>browser-profiles.json</code>. These metadata files do not contain cookies or passwords; Chromium owns the separate profile partitions. Turning global agent access off overrides every chat&#39;s switch immediately. With global access on, the chat&#39;s <strong>Session settings</strong> switch can still disable control for that conversation. The browser toolbar does not contain a second access switch. Files and explicit MCP preview requests continue to open in the inspector&#39;s Browser tab.</p><p><img src="'+P+'" alt="Desktop Browser settings with demo data"></p><p>This flow is desktop-only; the web and phone inspector has no Browser tab.</p><p><img src="'+_+'" alt="Working-tree changes beside a demo conversation"></p><img src="'+A+'" alt="Changes tab in the inspector on a phone" width="260"><p><img src="'+q+'" alt="Markdown editing beside a demo conversation"></p><p><img src="'+R+'" alt="Terminals"></p><p>Browser terminals for shells and coding agents, with split panes and Files and Git panels beside them. Terminals run on the selected execution host. See <a href="./terminal-workspace">Terminal workspace</a>.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Create, edit and archive projects. A project has a name, description, tags and an optional Git remote URL. Deleting a project deletes its memories and scratchpads and keeps its tasks, jobs and sessions without a project.</p><h2 id="memories" tabindex="-1">Memories <a class="header-anchor" href="#memories" aria-label="Permalink to &quot;Memories&quot;">​</a></h2><p>Short project facts (ports, conventions, decisions) that agents load at session start. Create, edit, and view each memory&#39;s change history. Under <strong>Knowledge → Memories</strong>.</p><h2 id="knowledge" tabindex="-1">Knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;Knowledge&quot;">​</a></h2><p><img src="'+O+'" alt="Knowledge"></p><p>Knowledge bases: upload PDFs, Office files, HTML, CSV and Markdown, write Markdown in place, or register a folder to copy in. Search returns cited passages. Each knowledge base can have a digest agent that maintains it on a schedule.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p><img src="'+j+'" alt="Jobs"></p><p>Scheduled and on-demand automation. A job runs a shell command, an agent or creates a task, triggered manually, by cron, by a file watch, once, or by a webhook. Each job keeps its run history with logs and linked agent sessions.</p><p>The job editor uses <strong>Trigger</strong>, <strong>Destination</strong> and <strong>Settings</strong> tabs. Choose Manual, Webhook or Schedule; schedules offer time/day controls and <strong>Advanced cron</strong>, with an explicit timezone. Existing watch, one-shot and bridge-message jobs keep their trigger. New jobs stay disabled until you enable them; a disabled job can still run manually.</p><p>Destination selects the project, working directory and execution host (local or a configured SSH host). Commands offer sh, bash, zsh, fish, PowerShell and cmd presets, plus a custom executable and one argument per line. The script is appended as the final argument, so a custom interpreter needs its command option, such as <code>-c</code>. The interpreter must be installed on the destination. Host default uses sh on Unix and Windows PowerShell on Windows; jobs saved before this setting retain sh.</p><p>Agent jobs save a prompt, backend, optional model, explicit automatic tool approval and supported launch options. Agent and model use the same picker as Chat: enabled agents, models reported by the provider on the job&#39;s selected host/directory, Agent default and an explicit Custom model option. A saved model remains selectable if discovery is temporarily unavailable. Changing agents clears the previous model and launch options. New agent jobs default to an isolated, detached Git worktree for each run. <code>HEAD</code> inherits the project checkout&#39;s current commit; override it with a branch or remote-tracking ref. ORC does not fetch, reset or push the base. <strong>Clean up worktree after a successful run</strong> is off by default. When enabled, cleanup removes only a successful, clean worktree with no commits absent from its starting base; failed runs, untracked/ignored files and new commits are retained. Run history records the path and cleanup result. HTTP-only agent backends cannot use these local host, worktree or environment settings.</p><p>Environment variables live under Settings. Mark a value <strong>Secret</strong> to mask its input, encrypt it at rest and omit its value from read responses. After saving, leave a saved secret blank to keep it; enter a replacement to rotate it. Exact secret values are redacted from job output and saved agent summaries, including across output chunks. This does not scrub transformed values or files and logs written by the script itself. Values are single-line; <code>ORC_</code> names are reserved. Back up <code>~/.orc/secret.key</code> with the database: saved secrets cannot be decrypted without that machine key.</p><p>To see a result, open the job and select <strong>View result</strong> under <strong>Recent runs</strong>. This shows the saved output and errors. <strong>Session summary</strong> opens the audit record. For an agent run with a native session ID, <strong>Open agent session</strong> opens the actual conversation in the chat page&#39;s session viewer, where the transcript/resume controls apply. ORC discovers that conversation on the run&#39;s own host without changing the globally selected host. If the provider has not retained a conversation yet, the saved result remains available and the interface explains that the native conversation is missing.</p><p><img src="'+I+'" alt="Job schedule editor"></p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>Inbound event sources. Configure a webhook once, then connect it to one or more jobs, each with its own event filters and action.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>When a session you are not viewing needs your approval, has a question or fails, ORC shows a <strong>Needs you</strong> notification and plays a short chime. Notifications settle for about one second before appearing and repeated snapshots do not repeat the alert. The header bell opens a menu containing generic notifications, including human requests, agent outcomes and job results. Open a request to answer or review its action. Read and dismissed state is shared across clients.</p><p>Desktop browsers show toasts. Needs-you toasts stay until dismissed or resolved; <strong>Done</strong> toasts are silent and close after six seconds, pausing on hover or focus. Sessions finishing together collapse into one notification. Use <strong>Alt+N</strong> or <strong>Open notifications</strong> in the command palette to reach notifications. On a phone, pull down from the very top of the screen with two fingers to open the notification center from the chat, like the system shade.</p><p>On all screens, the bell in the workspace header shows an unread count, including while the chat is open. New notifications never open the panel automatically. Tap the bell to read or dismiss them. History remains until dismissed or expired (30 days by default). Configure notification and audit retention in Settings → Notifications → Automatic cleanup. See <a href="./notifications">Notifications</a> and <a href="./human-requests">Human requests</a>.</p><p><strong>Settings → Notifications → Sound</strong> controls the browser chime, volume and per-project sound mute. Preferences are saved in this browser. Audio starts after your first interaction. Browser/PWA push remains separately opt-in and requires HTTPS (and Home Screen installation on iOS); it delivers background approvals, questions, chat replies and job results while ORC is unfocused. Job pushes follow the job&#39;s notify setting and start with new runs. See <a href="./install">Installation</a>.</p><p>The Electron desktop app also sends native notifications while its window is unfocused, minimized or hidden. Clicking one brings ORC forward, opens its destination and marks that notification read, clearing it from the inbox. A grouped done toast opens its destination only; clear the collapsed items from the notification menu. Done notifications are silent; native Needs-you sound follows the OS.</p><h2 id="browser-app-and-updates" tabindex="-1">Browser app and updates <a class="header-anchor" href="#browser-app-and-updates" aria-label="Permalink to &quot;Browser app and updates&quot;">​</a></h2><p>The dashboard installs as a browser app and serves an offline shell when the network is unreachable. An open tab or installed app runs the build it was loaded with, and the server replaces that build when it is updated. Reaching a page whose code is gone then reloads the app once, without asking, so unsaved input in the current page is lost; the reload loads the current build. If it does not fix the problem, ORC shows the failing error with <strong>Reload</strong> and <strong>Copy details</strong> instead of a generic error page, so a report carries the real message and stack.</p><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Lifecycle and knowledge events with filters and expandable details. Recorded session summaries remain in collapsed history. Audit retention defaults to 90 days and is configurable in Settings → Notifications → Automatic cleanup. Use the chat page&#39;s session list and viewer to read full conversations or resume an agent.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>Reusable agent instructions stored as skill folders. Import skills from a repository or from local agent folders, create your own, edit files, view history, and assign skills to projects. See <a href="./skills">Skills</a>.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>Packages bundle instructions, skills and tools for reuse. Launch a package in chat or a terminal on the host and folder you choose. See <a href="./agent-packages">Agent packages</a>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>Shared specialist agent definitions: instructions, model and tools, reusable across coding agents and packable into packages. Under <strong>Library → Agents</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Applied rules and their outcomes per workspace, plus rule settings for enforcement and agent assignment. See <a href="./agent-rules">Agent rules</a>.</p><h2 id="scratchpads" tabindex="-1">Scratchpads <a class="header-anchor" href="#scratchpads" aria-label="Permalink to &quot;Scratchpads&quot;">​</a></h2><p>Working documents, diagrams and HTML pages that you or an agent create and come back to. Agents use the <code>pad_*</code> MCP tools. Share one by copying its link.</p><p>HTML pads receive the <strong>ORC HTML kit</strong> in both the editor preview and chat artifacts: dashboard theme tokens, base styles, cards, tables, stats, badges, tabs and chart wrappers. Use <code>orc-*</code> classes to build a native-looking page without a custom <code>&lt;style&gt;</code> block. The kit is inlined at render time, needs no network request, and does not change the saved HTML. Custom CSS and JavaScript still work.</p><p>Pin the kit stylesheet in your HTML head to keep its version as the kit evolves:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orc-kit&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Bundled older versions remain available. A missing or unknown version uses the current kit. Both previews follow the dashboard&#39;s light/dark theme; changing the theme rebuilds the iframe document, resetting its running scripts and local UI state. The saved pad content stays the same.</p><p>Kit tabs support clicking, Left/Right arrows with wrapping, and Home/End. Only the selected panel is shown. The kit does not grant ORC API access: editor pads still require <strong>Render with ORC access</strong>, and chat artifacts retain their opaque sandbox and network-blocking policy. Prefer inline SVG for charts that must work in both views; a CDN chart library is blocked in chat.</p><p>For concise component markup, use built-in custom elements such as <code>&lt;orc-card&gt;</code>, <code>&lt;orc-stat label=&quot;Open tasks&quot; value=&quot;12&quot;&gt;</code>, <code>&lt;orc-badge tone=&quot;success&quot;&gt;</code>, <code>&lt;orc-table&gt;</code> and <code>&lt;orc-chart&gt;</code>. <code>&lt;orc-tabs&gt;</code> generates accessible tab controls from labeled <code>&lt;orc-tab&gt;</code> panels. These components reuse the kit with no additional dependencies or network requests; ordinary HTML with <code>orc-*</code> classes remains supported.</p><p>Agents can load the component list, copy-paste skeleton and chart guidance with <code>skill_read</code> for <code>orc-platform</code>, ref <code>references/html-kit.md</code>. See <a href="./skills">Skills</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+E+'" alt="Settings"></p><table tabindex="0"><thead><tr><th>Section</th><th>Controls</th></tr></thead><tbody><tr><td>General</td><td>Theme (dark or light, saved on the server), interface font size — default, large or extra large — saved in this browser, terminal font for new terminals, and the desktop preview browser.</td></tr><tr><td>Hosts</td><td>One list of hosts with <strong>API</strong> and <strong>SSH</strong> type badges. <strong>API</strong> rows are ORC servers this client can talk to: in a browser, save several server addresses with optional access tokens and proxy headers, then switch between them; the desktop app keeps its local/remote choice, token and headers in its data folder. The <strong>SSH</strong> row is where that server runs agents, terminals and git: <strong>This ORC server</strong>&#39;s own machine, which carries both badges because it also serves the dashboard, or an alias from its <code>~/.ssh/config</code>.</td></tr><tr><td>Agents</td><td><strong>Providers</strong> chooses which coding agents appear in the chat agent picker, channel agent choices and the terminal launcher. Claude Code, Codex and Pi are native; OpenCode runs over direct ACP; Cursor, Gemini CLI, GitHub Copilot, Qwen Code, Factory Droid, Kimi CLI, Kiro CLI and any custom agent id run through ACPX. First startup selects installed agents from Codex, Claude, Cursor, Gemini CLI and OpenCode and saves that selection. Copilot can be enabled in Settings. Later selections are preserved even if an installation is missing. The terminal launcher only lists enabled agents installed on the selected host. <strong>Chat</strong> sets default models, instructions, tools and permission mode. <strong>MCP</strong> builds the MCP config snippet for your agent; see <a href="./connect-agents">Connect agents</a>.</td></tr><tr><td>Connections</td><td><strong>Channels</strong> connects Telegram and Slack. <strong>Integrations</strong> manages APIs and MCP servers in the <code>spec</code> CLI registry.</td></tr><tr><td>Knowledge</td><td>Parser, embeddings and knowledge defaults</td></tr><tr><td>Notifications</td><td>In-app updates, browser chime/volume/project mute, opt-in browser/PWA push for background approvals, questions, chat replies and job results, the question and approval dismissal period, and notification/audit cleanup. Push needs HTTPS.</td></tr><tr><td>Usage</td><td>Request-level token usage and provider quotas</td></tr><tr><td>Security</td><td>Sign-in status and sign-out, default sign-in lifetime, allowed web origins, access tokens (minted by entering the secret)</td></tr><tr><td>About</td><td><strong>Restart ORC server</strong> (closes terminals, keeps settings, reconnects), data locations, and server, desktop and Electron versions, platform, runtime, data folder, uptime, project links, and desktop update channel</td></tr></tbody></table><p>On a phone, Settings opens a grouped list of sections; tapping one opens its panel, and the back arrow returns to the list. On desktop, the same groups appear in the sidebar.</p><p>In a browser, <strong>Hosts → Add server</strong> saves another ORC address with an optional access token and proxy headers, so you can switch installations and come back. The token is sent as a Bearer token, and header names that look secret (token, key, secret, password, cookie) are masked in the form. Values are stored in this browser. Switching records the previous server, so the sign-in screen can return you there if the new one needs different credentials. A remote server has to list this dashboard&#39;s origin under <strong>Security</strong>, and should use HTTPS: a plain-http address sends its token and headers over the network unencrypted. Prefer a revocable access token to the API secret: saved values are readable by scripts on this dashboard&#39;s origin.</p><p><strong>This ORC server</strong> always means the machine running the connected ORC installation, never the browser&#39;s machine. <strong>Change</strong> on the SSH row picks that server&#39;s own machine or an SSH alias from its <code>~/.ssh/config</code>. The choice stays server-wide: it affects every client using that ORC installation, and open terminals and conversations keep the host they started on. A new chat can pin one of those execution hosts in its workspace chip without changing the default: the list offers the connected server itself — the remote machine, running work directly without SSH — followed by its SSH aliases.</p><p><img src="'+L+'" alt="Chat host list on a remote server: This ORC server (orc.example.com) above its SSH aliases"></p><p>The desktop app stores its selected server, token and headers in <code>connection.json</code> in the app&#39;s data folder. This is a client-side target, separate from the server&#39;s <code>~/.orc/config.json</code>; switching servers does not repoint the CLI or stdio MCP. The integrated preview browser, local file picker, update controls and native notifications are available only in the local dashboard, so a remote window does not show them.</p><p><img src="'+B+'" alt="Desktop Hosts settings with a remote server and proxy headers"></p><img src="'+D+'" alt="Hosts settings on a phone" width="260"><p><img src="'+H+'" alt="Coding agents settings"></p><p>Enabled agents, including custom ACPX ids, appear in the chat agent picker:</p><p><img src="'+F+'" alt="Chat agent picker"></p><h2 id="chat-turn-progress" tabindex="-1">Chat turn progress <a class="header-anchor" href="#chat-turn-progress" aria-label="Permalink to &quot;Chat turn progress&quot;">​</a></h2><p>Finished turns fold tool calls and intermediate narration into one expandable line; your message and the final reply remain visible. Expand it to inspect file diffs, commands and output, reads, and searches. Failed tools stay marked.</p><p>During a response, a quiet status line shows elapsed time and the current tool. Scrolling up pauses automatic following; <strong>Jump to latest</strong> returns to the bottom. Stop remains beside Send. Working indicators are static.</p><p>Each turn keeps its duration and completed, stopped, or failed outcome across reloads. Duration uses the agent&#39;s reported value when available, otherwise server elapsed time, including waits for input. Older turns without timing show counts only. Stopped turns retain partial work; unfinished tool calls read <strong>Incomplete</strong>. Individual tool durations are not shown.</p><p>A turn that goes quiet does not run forever: after 15 minutes without any agent activity ORC stops it, and the conversation and a notification say it was stopped for inactivity. A turn waiting for your answer or approval, or with a command still running, is not idle and is not stopped; a 4-hour absolute limit still applies so a stuck agent cannot hold a chat worker indefinitely.</p><h2 id="composer-controls" tabindex="-1">Composer controls <a class="header-anchor" href="#composer-controls" aria-label="Permalink to &quot;Composer controls&quot;">​</a></h2><p>The composer groups folder, branch, agent/model and permissions into compact controls. Phones and narrow desktop panels use icons; wide composers show labels. While a reply is running, <strong>Send</strong> joins that turn when the backend accepts steering (Codex, Claude, Pi and OpenCode), so the agent reads the message before its next step. <strong>While responding</strong> in Session settings → Customize switches the conversation to <strong>Queue for the next turn</strong>; new chats take that default from Settings → Chat. The companion control beside Stop performs the other action either way, so both stay one press away. Attachments always queue, because steering carries text only. When the turn cannot take the message — the reply is still starting, the backend answers one message at a time, or every chat worker is busy — the message stays queued and sends when the turn ends, without an error. A steer whose delivery the agent never confirmed is not resent: chat keeps the text and asks you to check the conversation first, because the message may already be there. Open the pending list to edit a message, move it up or down, remove it, or send it ahead of the current reply. An expanded pending list stays open across busy-worker retries. After it drains, the next list starts collapsed. If a first send loses its connection, chat looks for the original message and reconnects to its thread. Recovery stops after 15 seconds, or 60 seconds when the server may still be preparing the turn. If recovery cannot find it, the message returns to a paused queue with its attachments. Retrying keeps the message&#39;s ID so the server can recover the original turn without starting another one. Every icon has an accessible name and opens its picker with the full details; phone touch targets are at least 44px. Send stays visible at the right.</p><p>The folder picker shows the full path, copy action, recent folders, host choices when configured, and browsing. Branch/worktree controls appear for Git folders. <strong>Run in</strong> keeps the current checkout, creates a worktree from the current branch, creates one from the repository default branch (for example <code>origin/main</code>), or creates one from any local or remote branch you pick. The branch chip shows the chosen base. Bases come from refs already in the checkout; ORC does not fetch before creating the worktree. After launch the folder and branch chips stay in the composer as session information: the folder opens its full path with a copy action, and the branch shows the checkout&#39;s working branch. The execution folder itself is fixed for the session.</p><img src="'+M+'" alt="Run in options in the desktop chat panel" width="380"><img src="'+W+'" alt="Run in options for the current checkout, the current branch, the default branch and another branch" width="260"><p><img src="'+U+'" alt="Composer with the session folder, branch and permission chips"></p><img src="'+G+'" alt="Phone composer with folder, branch and permission icons" width="260"><p>Changing agent after launch starts a separate session. The model picker disables changes during a response or when the backend selects its own model. Effort stays in agent options. The permissions chip shows the open session&#39;s mode — including <strong>Ask in chat</strong> — when the backend supports changing it live.</p><p><strong>Session settings</strong> in the chat header organizes the conversation into tabs. <strong>Overview</strong> shows the agent, model, execution host and folder, backend, last activity, tools connection and capabilities, plus the identifiers: the ORC chat ID, the agent&#39;s native session ID used for resume, and the discovered session ID this chat continues when it was resumed. Each identifier can be copied. <strong>Customize</strong> holds permissions, while-responding behaviour, agent launch options, session instructions and agent browser control. <strong>Analytics</strong> counts messages, turns, tool calls and failures from the transcript, shows start, last-activity and turn timings, and reports context and cache usage when the session records it. Explanations sit behind the info icon beside each label; new-chat defaults remain in Settings → Agents → Chat.</p><p><img src="'+N+'" alt="Session settings overview with the ORC, agent and resume identifiers"><img src="'+K+'" alt="Session analytics with counts, turn timings and cache reuse"></p><img src="'+z+'" alt="Session settings customization on a phone" width="260"><p>Pasting at least 16 KiB or 200 lines attaches the text as <code>pasted-text-N.txt</code>. Use <strong>Ctrl/Cmd+Shift+V</strong> to paste inline instead. Typing <code>@</code> does not attach files.</p><img src="'+J+'" alt="Compact composer icons on a phone" width="260"><h2 id="desktop-app-only" tabindex="-1">Desktop app only <a class="header-anchor" href="#desktop-app-only" aria-label="Permalink to &quot;Desktop app only&quot;">​</a></h2><p>The desktop app is an Electron shell around the same dashboard. On top of the browser experience it:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Detail</th></tr></thead><tbody><tr><td>Runs the daemon for you</td><td>Reuses a verified local daemon, including one on another port, or starts the bundled <code>orc</code> daemon</td></tr><tr><td>Configures auth</td><td>Generates an API secret for a daemon it starts when none is set, and sends the configured secret automatically. No sign-in screen.</td></tr><tr><td>Installs the CLI</td><td><code>~/.orc/bin/orc</code>, added to your shell <code>PATH</code></td></tr><tr><td>Tray icon</td><td><strong>Open orc</strong>, <strong>Start at login</strong> toggle, <strong>Quit orc</strong></td></tr><tr><td>Start at login</td><td>On by default, starts hidden in the tray</td></tr><tr><td>Keeps running when closed</td><td>Closing the window hides it; the tray icon and the daemon keep running. <strong>Quit orc</strong> in the tray (or <strong>Cmd+Q</strong> on macOS) quits.</td></tr><tr><td>Recovers from startup failures and crashes</td><td>Waits briefly for a starting daemon, then offers <strong>Retry</strong> or <strong>Quit</strong> if it cannot connect</td></tr><tr><td>Remembers the window</td><td>Size, position and maximized state</td></tr><tr><td>Updates</td><td>Installed macOS, Windows and Linux apps check GitHub Releases at startup and every four hours, download in the background, and offer <strong>Restart to update</strong></td></tr></tbody></table><p>Quitting the app (<strong>Quit orc</strong>) stops the daemon only if the app started it.</p><p>If another application occupies the configured port, desktop automatically starts ORC on an available port bound to <code>127.0.0.1</code>. It saves the successful endpoint in <code>~/.orc/config.json</code>, so the CLI and stdio MCP use the same port by default. Explicit CLI flags, environment variables and project configuration keep their normal precedence; update pinned ports or URLs in external integrations yourself.</p><p>Desktop checks the daemon&#39;s runtime identity, compatible version (same major and minor), database, configuration and authentication before attaching. It never starts another daemon while the daemon PID is alive, even if that daemon is unhealthy or uses different data. Authentication and configuration errors offer <strong>Retry</strong> or <strong>Quit</strong>, with the reason shown. It does not stop an existing daemon or the application occupying the preferred port.</p><p><strong>Upgrading an already-running older daemon:</strong> releases without <code>daemon.json</code> cannot provide this identity check. Stop that daemon once and start it with the updated ORC, then choose <strong>Retry</strong> in desktop. Desktop does not attach to an unverified daemon or send it the configured secret.</p><p>Command-line flags for the app executable:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--hidden</code></td><td>Start without opening a window</td></tr><tr><td><code>--quit</code></td><td>Quit the running instance and the daemon it started</td></tr></tbody></table><p>Links to other sites open in the desktop inspector&#39;s Browser tab. Use its external-link icon or Ctrl/Cmd-click a web link to open your system browser.</p><p>Install a desktop build containing this updater manually once. Older builds do not have an updater and cannot automatically install the feature itself; subsequent macOS, Windows and Linux updates can use the flow below.</p><p>An installed macOS, Windows or Linux app checks <a href="https://github.com/niradler/orc/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for updates when it starts and every four hours. The download runs in the background. <strong>Settings → About</strong> shows the current version, the update channel, <strong>Check now</strong>, and the last result. <strong>Restart to update</strong> installs the download; quitting alone does not apply it. The app stops the daemon it started, then the new version starts that daemon again. Tasks and sessions stay in <code>~/.orc</code>. A daemon the app did not start is left running.</p><p><strong>Stable</strong> uses the latest GitHub release. <strong>Preview</strong> also accepts a newer prerelease. Uncheck <strong>Check for updates</strong> to stop automatic checks; <strong>Check now</strong> still works. These choices are stored in the desktop app&#39;s own settings, not in <code>~/.orc/config.json</code>. Source runs and <code>electron .</code> do not download updates.</p><p>Wait for an active check or download to finish before changing channels. Changing channels discards the previous channel&#39;s ready update. Failed settings saves retain the prior preferences and show an error; failed update actions can be retried.</p><p>Windows installs the NSIS package. Linux replaces the AppImage. macOS verifies the release disk image and its app bundle, then replaces the app through a separate installer helper and keeps the previous app for recovery. The Mac installation folder must be writable; updates work without a paid Apple developer account. macOS first-open approval for an unnotarized app can still apply. Manual upgrade steps remain in <a href="./install#upgrading">Upgrading</a>.</p>',163)])])}const oe=s(V,[["render",Q]]);export{se as __pageData,oe as default};
